<?php
/** Native bilingual team pages. Setup is one-time; everyday maintenance uses Pages. */
defined('ABSPATH') || exit;
add_action('enqueue_block_assets',function(){wp_enqueue_style('tkc-team-page',plugins_url('team-page.css',__FILE__),[],'1.7.5');});
add_action('admin_menu',function(){add_management_page('Team page setup','Team page setup','manage_options','tkc-team-page','tkcteam_admin');});
function tkcteam_admin(){if(!current_user_can('manage_options'))return;echo '<div class="wrap"><h1>Our team — page setup / 独立团队页面</h1>';if($pages=get_option('tkc_team_pages')){echo '<p>Team pages are ready. Maintain photos, roles and LinkedIn links in Pages; no code is needed.</p>';foreach($pages as$lang=>$id)echo '<p><a href="'.esc_url(get_edit_post_link($id)).'">Edit '.esc_html(strtoupper($lang)).'</a> · <a href="'.esc_url(get_permalink($id)).'">View</a></p>';echo '</div>';return;}echo '<p>Create native English and Estonian team pages, move the empty Our team placeholder out of About us, and insert the new page after About us and before Resource in each primary menu. Existing portraits remain unchanged; display crops use the team page styles.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcteam_install');echo '<input type="hidden" name="action" value="tkcteam_install"><p><label>Shuang Qi photo attachment ID <input type="number" name="shuang" min="1" required></label></p><p><label>Lanxiang Zhang photo attachment ID <input type="number" name="lanxiang" min="1" required></label></p>';submit_button('Create team pages / 建立团队页面');echo '</form></div>';}
function tkcteam_member($id,$name,$roles,$url,$photo_class,$lang,$languages,$quote){$image=wp_get_attachment_image_url($id,'full');$out='<!-- wp:column --><div class="wp-block-column"><!-- wp:group '.wp_json_encode(['metadata'=>['name'=>$name],'className'=>'tkc-team-member','layout'=>['type'=>'default']]).' --><div class="wp-block-group tkc-team-member">';$out.='<!-- wp:image '.wp_json_encode(['id'=>$id,'sizeSlug'=>'full','linkDestination'=>'none','className'=>'tkc-team-portrait '.$photo_class]).' --><figure class="wp-block-image size-full tkc-team-portrait '.esc_attr($photo_class).'"><img src="'.esc_url($image).'" alt="'.esc_attr($name).'" class="wp-image-'.$id.'"/></figure><!-- /wp:image -->';$out.='<!-- wp:heading --><h2 class="wp-block-heading">'.esc_html($name).'</h2><!-- /wp:heading --><!-- wp:paragraph {"className":"tkc-team-role"} --><p class="tkc-team-role">'.implode('<br>',array_map('esc_html',$roles)).'</p><!-- /wp:paragraph -->';$out.='<!-- wp:paragraph {"className":"tkc-team-languages"} --><p class="tkc-team-languages">'.esc_html($languages).'</p><!-- /wp:paragraph --><!-- wp:paragraph {"className":"tkc-team-quote"} --><p class="tkc-team-quote">'.esc_html($quote).'</p><!-- /wp:paragraph -->';$link=$lang==='et'?$name.' LinkedInis':$name.' on LinkedIn';$out.='<!-- wp:paragraph {"className":"tkc-team-link"} --><p class="tkc-team-link"><a href="'.esc_url($url).'" target="_blank" rel="noreferrer noopener">'.esc_html($link).'</a></p><!-- /wp:paragraph --></div><!-- /wp:group --></div><!-- /wp:column -->';return $out;}
function tkcteam_content($photos,$lang){$et=$lang==='et';$title=$et?'Meie meeskond':'Our team';return '<!-- wp:group {"className":"tkc-page-intro tkc-section","layout":{"type":"default"}} --><div class="wp-block-group tkc-page-intro tkc-section"><!-- wp:paragraph {"className":"tkc-label"} --><p class="tkc-label">The Kind Circle MTÜ</p><!-- /wp:paragraph --><!-- wp:heading {"level":1} --><h1 class="wp-block-heading">'.$title.'</h1><!-- /wp:heading --></div><!-- /wp:group --><!-- wp:group {"className":"tkc-body tkc-team-page","layout":{"type":"default"}} --><div class="wp-block-group tkc-body tkc-team-page"><!-- wp:columns {"className":"tkc-team-grid"} --><div class="wp-block-columns tkc-team-grid">'.tkcteam_member($photos[0],'Shuang Qi (Emma)',$et?['Asutaja','Kogukonnaprojektide korraldaja']:['Founder','Community Project Organizer'],'https://www.linkedin.com/in/shuang-qi-emma/','tkc-team-emma',$lang,$et?'Keeled · hiina, inglise, korea':'Languages · Chinese, English, Korean',$et?'“Maailm on nii suur. Avastame seda koos!”':'“The world is a big place. Let’s experience it together.”').tkcteam_member($photos[1],'Lanxiang Zhang (Alex)',$et?['Digisüsteemide ja teadmusjuhtimise vabatahtlik']:['Digital Systems & Knowledge Management Volunteer'],'https://www.linkedin.com/in/lanxiang-zhang/','tkc-team-lanxiang',$lang,$et?'Keeled · hiina, inglise':'Languages · Chinese, English',$et?'“Aitan muuta teadmiste jagamise ja kogukondade ühendamise lihtsamaks.”':'“Making knowledge easier to share, and communities easier to connect.”').'</div><!-- /wp:columns --></div><!-- /wp:group -->';}
function tkcteam_about_without_placeholder($content,$lang){$name=$lang==='et'?'Meie meeskond':'Our team';$pattern='~<!-- wp:group [^\r\n]*"name":"'.preg_quote($name,'~').'"[^\r\n]*-->.*?<!-- /wp:group -->~s';$matches=[];preg_match_all($pattern,$content,$matches);if(count($matches[0])!==1||trim(wp_strip_all_tags($matches[0][0]))!==$name)throw new RuntimeException('Team placeholder changed. No About content was removed.');return str_replace($matches[0][0],'',$content);}
add_action('admin_post_tkcteam_install',function(){if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcteam_install');if(get_option('tkc_team_pages')){wp_safe_redirect(admin_url('tools.php?page=tkc-team-page'));exit;}$photos=[absint($_POST['shuang']??0),absint($_POST['lanxiang']??0)];foreach($photos as$id)if(!$id||!wp_attachment_is_image($id)||!wp_get_attachment_image_url($id,'full'))wp_die('Choose two valid photo attachments.');$map=get_option('tkc_page_map',[]);$menus=get_option('tkc_menu_map',[]);$locations=get_theme_mod('nav_menu_locations',[]);$prepared=[];$primary=[];$backup=['at'=>gmdate('c'),'map'=>$map,'pages'=>[],'menus'=>[]];
 try{foreach(['en','et']as$lang){$id=(int)($map['about-us'][$lang]??0);$p=get_post($id);if(!$p)throw new RuntimeException('About page missing.');$prepared[$id]=tkcteam_about_without_placeholder($p->post_content,$lang);$backup['pages'][$id]=['title'=>$p->post_title,'content'=>$p->post_content];$mid=absint($menus[$lang]??($locations['primary-'.$lang]??0));$items=$mid?wp_get_nav_menu_items($mid):[];$about=false;$resource=false;foreach($items?:[]as$item){if((int)$item->object_id===$id)$about=true;if((int)$item->object_id===(int)($map['resources'][$lang]??0))$resource=true;$backup['menus'][$item->ID]=['post'=>get_post($item->ID,ARRAY_A),'meta'=>get_post_meta($item->ID)];}if(!$about||!$resource)throw new RuntimeException('Primary menu or About/Resource link missing.');$primary[$lang]=[$mid,$items,$id];}}
 catch(Throwable $e){wp_die(esc_html($e->getMessage()));}
 update_option('tkc_team_page_backup',$backup,false);$pages=[];foreach(['en','et']as$lang){$id=wp_insert_post(wp_slash(['post_type'=>'page','post_title'=>$lang==='en'?'Our team':'Meie meeskond','post_name'=>$lang==='en'?'our-team':'our-team-et','post_status'=>'draft','post_content'=>tkcteam_content($photos,$lang),'comment_status'=>'closed']),true);if(is_wp_error($id))wp_die(esc_html($id->get_error_message()));$pages[$lang]=(int)$id;if(function_exists('pll_set_post_language'))pll_set_post_language($id,$lang);update_post_meta($id,'tkc_description',$lang==='en'?'Meet Shuang Qi and Lanxiang Zhang, the people contributing to The Kind Circle MTÜ.':'Tutvu The Kind Circle MTÜ meeskonnaliikmete Shuang Qi ja Lanxiang Zhangiga.');}if(function_exists('pll_save_post_translations'))pll_save_post_translations($pages);
 foreach($pages as$id){$res=wp_update_post(['ID'=>$id,'post_status'=>'publish'],true);if(is_wp_error($res))wp_die(esc_html($res->get_error_message()));}
 foreach($prepared as$id=>$content)wp_update_post(wp_slash(['ID'=>$id,'post_content'=>$content]));
 foreach($primary as$lang=>$data){list($mid,$items,$about)=$data;$new=wp_update_nav_menu_item($mid,0,['menu-item-title'=>$lang==='en'?'Our team':'Meie meeskond','menu-item-object-id'=>$pages[$lang],'menu-item-object'=>'page','menu-item-type'=>'post_type','menu-item-status'=>'publish','menu-item-parent-id'=>0]);if(is_wp_error($new))wp_die(esc_html($new->get_error_message()));$ordered=[];foreach($items as$item){$ordered[]=$item->ID;if((int)$item->object_id===$about)$ordered[]=$new;}foreach($ordered as$i=>$item)wp_update_post(['ID'=>$item,'menu_order'=>$i+1]);}
 update_post_meta($photos[0],'_wp_attachment_image_alt','Shuang Qi');update_post_meta($photos[1],'_wp_attachment_image_alt','Lanxiang Zhang');$map['our-team']=$pages;update_option('tkc_page_map',$map,false);update_option('tkc_team_pages',$pages,false);wp_safe_redirect(admin_url('tools.php?page=tkc-team-page'));exit;
});
